let JSDOM;try{({JSDOM}=require('jsdom'))}catch{}
const flush=async()=>{for(let i=0;i<8;i++)await new Promise(r=>setImmediate(r))};
function fixture(fail=false){const dom=new JSDOM('<header><div id="title"><button id="featureBack">Experiences</button></div></header><section class="experiences-page"><nav class="experiences-tabs">人生时间线 · IF 世界</nav><main class="experience-future-panel"></main></section>',{runScripts:'outside-only'}),w=dom.window;w.eval(fs.readFileSync(require.resolve('../scripts/timeline-core.js'),'utf8'));w.eval(fs.readFileSync(require.resolve('../scripts/if-world.js'),'utf8'));const node={id:'n',title:'入学',startAge:12},role={name:'甲',experienceCharacterId:'r',lifeTimeline:{entries:[node]},ifWorld:{ownerId:'r',branches:[{id:'b',roleId:'r',sourceNodeId:'n',nodeSnapshot:node,title:'入学 · IF',createdAt:1700000000000,messages:[],settings:{},growthBinding:{roleId:'r',age:12,stageId:'s'}}],dreams:[]}},host=w.document.querySelector('main');let calls=0;const options={title:w.document.querySelector('#title'),ifSourceAge:()=>12,ifGrowthBinding:()=>({roleId:'r',age:12,stageId:'s'}),ifOriginalWorld:()=>'原世界的城镇与学校设定',ifNormalizeSettings:value=>JSON.parse(JSON.stringify(value)),state:{char:0,characters:[role]},esc:s=>String(s).replaceAll('<','&lt;'),isActive:()=>true,persist:async()=>{},confirm:()=>true,ifSettings:()=>({}),ifStyleOptions:()=>[],ifStylePrompt:()=>'',ifBranchGrowthBinding:()=>role.ifWorld.branches[0].growthBinding,ifGrowthChoices:()=>[{id:'s',name:'少年'}],ifGrowthSetting:()=>'少年档案',ifPrompt:(r,b,m,rules)=>rules,analyze:async()=>{calls++;if(fail)throw Error('接口失败');return '新的 IF 开场剧情'}};w.IrisIfWorld.mount(options,host);host.querySelector('[data-if-node]').click();return{dom,w,host,role,calls:()=>calls,options}}
test('opening success enters a clean story page with an offline-style composer',{skip:!JSDOM},async()=>{const f=fixture();try{const {host,w}=f;assert.equal(host.querySelector('[data-if-page="story"]'),null);host.querySelector('.if-compose textarea').value='我来到学校';host.querySelector('.if-compose').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(host.querySelector('.if-compose button').disabled,true);await flush();assert.equal(f.calls(),1);assert.ok(host.querySelector('[data-if-page="story"]'));assert.equal(host.querySelector('.if-history').textContent.includes('新的 IF 开场剧情'),true);assert.equal(host.querySelector('.if-story-page>.if-source'),null);assert.ok(host.querySelector('.if-story-page>.if-compose'));assert.equal(host.querySelector('.if-subtabs,.if-settings,[data-if-select],.if-story-details,[data-if-save-dream]'),null);assert.ok(host.querySelector('.if-compose.composer .input-wrap .message-input'));assert.ok(host.querySelector('[data-if-reply]'));assert.ok(!host.textContent.includes('续写 IF'));assert.equal(f.role.ifWorld.branches[0].messages.length,2)}finally{f.dom.window.close()}});
