test('preset and custom worlds persist per branch and only the chosen world enters generation',{skip:!JSDOM},async()=>{const f=fixture();try{let prompt;f.options.analyze=async value=>{prompt=value;return '世界中的开场'};f.host.querySelector('[data-if-view="settings"]').click();assert.deepEqual([...f.host.querySelectorAll('[data-if-setting-tab]')].map(b=>b.textContent),['通用','文风','世界','其他']);f.host.querySelector('[data-if-setting-tab="world"]').click();const select=f.host.querySelector('[name=worldId]');assert.deepEqual([...select.options].map(o=>o.textContent),['原世界','哈利波特','古代','江湖','仙侠','民国架空','末日','Galgame','中式志怪','幽冥鬼城','西方哥特','星际 ABO']);select.value='magic';select.dispatchEvent(new f.w.Event('change'));assert.ok(f.host.querySelector('[data-if-world-preview]').textContent.includes('霍格沃茨'));f.host.querySelector('[data-if-settings]').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(f.role.ifWorld.branches[0].settings.worldId,'magic');f.host.querySelector('[data-if-view="story"]').click();f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.ok(prompt.includes('霍格沃茨'));assert.ok(!prompt.includes('空间站'));assert.ok(!prompt.includes('原世界的城镇与学校设定'));f.w.IrisIfWorld.back();f.host.querySelector('[data-if-node]').click();f.host.querySelector('.if-opening-new').click();await flush();f.host.querySelector('[data-if-view="settings"]').click();f.host.querySelector('[data-if-setting-tab="world"]').click();f.host.querySelector('[data-if-world-name]').value='海岛';f.host.querySelector('[data-if-world-setting]').value='群岛之间依靠帆船往来，保留角色性格。';f.host.querySelector('[data-if-world-add]').click();await flush();const settings=f.role.ifWorld.branches[1].settings;assert.equal(settings.customWorlds[0].name,'海岛');assert.equal(settings.worldId,settings.customWorlds[0].id);assert.ok(f.host.querySelector('[data-if-world-preview]').textContent.includes('帆船'));f.host.querySelector('[data-if-view="story"]').click();f.host.querySelector('.if-compose textarea').value='出航';f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.ok(prompt.includes('帆船'));assert.ok(!prompt.includes('霍格沃茨'));assert.equal(f.role.ifWorld.branches[0].originalWorld,'原世界的城镇与学校设定');assert.equal(f.role.lifeTimeline.entries.length,1)}finally{f.dom.window.close()}});
