test('opening deletion confirms its branch, updates count, and preserves timeline and dreams',{skip:!JSDOM},async()=>{const f=fixture();try{const timeline=JSON.stringify(f.role.lifeTimeline);f.role.ifWorld.branches[0].messages=[{mine:false,text:'要删除的开场'}];f.role.ifWorld.branches.push({...JSON.parse(JSON.stringify(f.role.ifWorld.branches[0])),id:'keep',messages:[{mine:false,text:'保留的开场'}]});f.role.ifWorld.dreams=[{id:'dream',roleId:'r',content:'已保存的梦',sourceBranchId:'b'}];f.w.IrisIfWorld.back();f.host.querySelector('[data-if-node]').click();assert.equal(f.host.querySelectorAll('.if-opening-picker .if-opening-bow,.if-opening-picker .if-timeline-bow').length,0);assert.ok(f.host.querySelector('[data-if-node] svg.if-timeline-bow .if-bow-loops'));const deleteButton=f.host.querySelector('[data-if-delete-opening="b"]');assert.ok(deleteButton.previousElementSibling.matches('time'));f.options.confirm=()=>false;deleteButton.click();await flush();assert.equal(f.role.ifWorld.branches.length,2);f.options.confirm=message=>{assert.match(message,/后续剧情/);return true};deleteButton.click();await flush();assert.deepEqual(Array.from(f.role.ifWorld.branches,b=>b.id),['keep']);assert.equal(f.host.querySelector('.if-opening-count').textContent,'1');assert.equal(f.host.querySelectorAll('.if-opening-card').length,1);assert.equal(f.role.ifWorld.dreams.length,1);assert.equal(JSON.stringify(f.role.lifeTimeline),timeline);f.host.querySelector('[data-if-delete-opening]').click();await flush();assert.equal(f.role.ifWorld.branches.length,0);assert.equal(f.host.querySelector('.if-opening-picker'),null);assert.equal(f.host.querySelector('.if-opening-count'),null)}finally{f.dom.window.close()}});
test('failed deletion retains its opening card with an inline error',{skip:!JSDOM},async()=>{const f=fixture();try{f.role.ifWorld.branches[0].messages=[{mine:false,text:'保留开场'}];f.w.IrisIfWorld.back();f.host.querySelector('[data-if-node]').click();f.options.persist=async()=>{throw Error('磁盘不可用')};f.host.querySelector('[data-if-delete-opening]').click();await flush();assert.equal(f.role.ifWorld.branches.length,1);assert.ok(f.host.querySelector('.if-picker-error').textContent.includes('保存失败'));assert.equal(f.host.querySelector('[data-if-delete-opening]').disabled,false)}finally{f.dom.window.close()}});
test('ribbon becomes butterflies once, disappears, and restores when returning',{skip:!JSDOM},async()=>{const f=fixture();try{f.role.ifWorld.branches[0].messages=[{mine:false,text:'开场'}];f.w.IrisIfWorld.back();const finishes=[],animated=[];f.w.Element.prototype.animate=function(frames,options){animated.push({element:this,frames,options});return{finished:new Promise(resolve=>finishes.push(resolve))}};const card=f.host.querySelector('[data-if-node]');card.click();card.click();assert.equal(animated.length,15);assert.equal(card.querySelectorAll('.if-bow-butterfly').length,7);assert.equal(card.getAttribute('aria-busy'),'true');assert.equal(f.host.querySelector('.if-opening-picker'),null);finishes.forEach(done=>done());await flush();assert.equal(f.host.querySelectorAll('.if-opening-picker').length,1);assert.equal(card.hasAttribute('aria-busy'),false);assert.equal(card.querySelector('.if-timeline-bow').style.opacity,'0');assert.equal(card.querySelector('.if-bow-burst'),null);f.host.querySelector('.if-opening-picker').dispatchEvent(new f.w.Event('cancel',{cancelable:true}));assert.equal(card.querySelector('.if-timeline-bow').style.opacity,'');}finally{f.dom.window.close()}});
