test('story composer sends multiline text, requests replies separately, and preserves an unsent draft',{skip:!JSDOM},async()=>{const f=fixture();try{f.role.ifWorld.branches[0].messages=[{mine:false,text:'已生成的开场'}];await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');let field=f.host.querySelector('.message-input');field.value='第一行\n第二行';field.dispatchEvent(new f.w.Event('input'));assert.equal(f.host.querySelector('[data-if-send]').hidden,false);field.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));assert.equal(f.role.ifWorld.branches[0].messages.length,1);f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(f.calls(),0);assert.equal(f.role.ifWorld.branches[0].messages.at(-1).text,'第一行\n第二行');field=f.host.querySelector('.message-input');assert.equal(field.value,'');assert.equal(f.host.querySelector('[data-if-send]').hidden,true);field.value='还没发送的草稿';field.dispatchEvent(new f.w.Event('input'));f.host.querySelector('[data-if-reply]').click();await flush();assert.equal(f.calls(),1);assert.equal(f.host.querySelector('.message-input').value,'还没发送的草稿');assert.equal(f.role.ifWorld.branches[0].messages.length,3);assert.equal(f.role.ifWorld.branches[0].messages.at(-1).mine,false)}finally{f.dom.window.close()}});
