function contextIfMessage(f,index){f.host.querySelector(`[data-if-message-index="${index}"] p`).dispatchEvent(new f.w.MouseEvent('contextmenu',{bubbles:true,cancelable:true}))}
async function messageFixture(){const f=fixture();Object.assign(f.role.ifWorld.branches[0],{messages:[{mine:false,text:'开场正文'},{mine:true,text:'用户回应'},{mine:false,text:'后续正文'}],summary:'包含旧消息的摘要',summaryAtRound:8,currentState:'旧状态'});await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');return f}
test('IF context actions edit multiline text, invalidate old summary, and keep other branches intact',{skip:!JSDOM},async()=>{const f=await messageFixture();try{const source=JSON.stringify(f.role.lifeTimeline);f.role.ifWorld.branches.push({...JSON.parse(JSON.stringify(f.role.ifWorld.branches[0])),id:'other'});const other=JSON.stringify(f.role.ifWorld.branches[1]);contextIfMessage(f,0);assert.deepEqual(Array.from(f.host.querySelectorAll('[data-if-message-action]'),button=>button.textContent),['编辑','删除','多选']);f.host.querySelector('[data-if-message-action="edit"]').click();const field=f.host.querySelector('.if-message-edit textarea');assert.equal(field.value,'开场正文');field.value='修改第一行\n修改第二行';f.host.querySelector('.if-message-edit').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(f.role.ifWorld.branches[0].messages[0].text,'修改第一行\n修改第二行');assert.equal(f.role.ifWorld.branches[0].summary,'');assert.equal(f.role.ifWorld.branches[0].summaryAtRound,undefined);assert.equal(f.role.ifWorld.branches[0].currentState,'');assert.equal(JSON.stringify(f.role.ifWorld.branches[1]),other);assert.equal(JSON.stringify(f.role.lifeTimeline),source);assert.equal(f.host.querySelector('.if-message-edit'),null)}finally{f.dom.window.close()}});
test('IF single and multi deletion confirm, preserve order, and keep the composer after deleting everything',{skip:!JSDOM},async()=>{const f=await messageFixture();try{contextIfMessage(f,1);f.options.confirm=()=>false;f.host.querySelector('[data-if-message-action="delete"]').click();await flush();assert.equal(f.role.ifWorld.branches[0].messages.length,3);contextIfMessage(f,1);f.options.confirm=()=>true;f.host.querySelector('[data-if-message-action="delete"]').click();await flush();assert.deepEqual(Array.from(f.role.ifWorld.branches[0].messages,m=>m.text),['开场正文','后续正文']);contextIfMessage(f,0);f.host.querySelector('[data-if-message-action="select"]').click();assert.equal(f.host.querySelector('.if-compose').hidden,true);assert.equal(f.host.querySelector('[data-if-message-index="0"]').getAttribute('aria-checked'),'true');assert.ok(f.host.querySelector('[data-if-message-index="0"] .message-selection-check .if-selection-butterfly'));assert.equal(f.host.querySelector('[data-if-message-index="1"] .message-selection-check').childElementCount,0);f.host.querySelector('[data-if-message-index="1"] p').click();assert.match(f.host.querySelector('.if-message-selection').textContent,/已选 2 条/);f.host.querySelector('[data-if-selection-delete]').click();await flush();assert.equal(f.role.ifWorld.branches[0].messages.length,0);assert.equal(f.host.querySelector('.if-message-selection'),null);assert.ok(f.host.querySelector('.if-chat-composer'));assert.equal(f.host.querySelector('.if-subtabs'),null);f.w.IrisIfWorld.back();await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');assert.ok(f.host.querySelector('.if-chat-composer'))}finally{f.dom.window.close()}});
test('IF failed edit and deletion retain original messages and keep retryable controls',{skip:!JSDOM},async()=>{const f=await messageFixture();try{f.options.persist=async()=>{throw Error('存储失败')};contextIfMessage(f,0);f.host.querySelector('[data-if-message-action="edit"]').click();f.host.querySelector('.if-message-edit textarea').value='编辑草稿';f.host.querySelector('.if-message-edit').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(f.role.ifWorld.branches[0].messages[0].text,'开场正文');assert.equal(f.host.querySelector('.if-message-edit textarea').value,'编辑草稿');f.host.querySelector('[data-if-edit-cancel]').click();contextIfMessage(f,0);f.host.querySelector('[data-if-message-action="delete"]').click();await flush();assert.equal(f.role.ifWorld.branches[0].messages.length,3);assert.match(f.host.querySelector('.if-feedback').textContent,/存储失败/);assert.equal(f.host.querySelector('[data-if-reply]').disabled,false)}finally{f.dom.window.close()}});
test('IF touch long press opens actions; moving to scroll cancels it',{skip:!JSDOM},async()=>{const f=await messageFixture();try{const timers=new Map();let next=0;f.w.setTimeout=callback=>{const id=++next;timers.set(id,callback);return id};f.w.clearTimeout=id=>timers.delete(id);const pointer=(type,x)=>new f.w.MouseEvent(type,{bubbles:true,cancelable:true,clientX:x,clientY:20});let text=f.host.querySelector('[data-if-message-index="0"] p');text.dispatchEvent(pointer('pointerdown',20));text.dispatchEvent(pointer('pointermove',45));assert.equal(timers.size,0);assert.equal(f.host.querySelector('.message-action-menu'),null);text.dispatchEvent(pointer('pointerdown',20));assert.equal(timers.size,1);[...timers.values()][0]();assert.ok(f.host.querySelector('.message-action-menu'));f.w.document.dispatchEvent(new f.w.Event('pointerup'));f.host.querySelector('[data-if-message-index="0"] p').click();assert.ok(f.host.querySelector('.message-action-menu'));f.host.querySelector('[data-if-message-action="select"]').click();assert.ok(f.host.querySelector('.if-message-selection'))}finally{f.dom.window.close()}});
function clickStoryTool(f,action){f.host.querySelector('[data-if-tools-toggle]').click();f.host.querySelector(`[data-if-story-tool="${action}"]`).click()}
test('IF plus opens four Chinese actions vertically and closes on outside tap',{skip:!JSDOM},async()=>{const f=await messageFixture();try{const trigger=f.host.querySelector('[data-if-tools-toggle]'),menu=f.host.querySelector('.if-story-tools-menu');assert.equal(menu.hidden,true);assert.ok(f.host.querySelector('.if-chat-composer').firstElementChild.matches('.if-story-tools'));trigger.click();assert.equal(trigger.getAttribute('aria-expanded'),'true');assert.deepEqual(Array.from(menu.querySelectorAll('.if-story-tool-label'),label=>label.textContent),['记入梦境','封存','清空','删除']);f.host.querySelector('.if-story-body').dispatchEvent(new f.w.Event('pointerdown',{bubbles:true}));assert.equal(menu.hidden,true);assert.equal(trigger.getAttribute('aria-expanded'),'false')}finally{f.dom.window.close()}});
test('IF dream summarizes the branch once and records explicitly chosen channels',{skip:!JSDOM},async()=>{const f=await messageFixture();try{let prompt,calls=0;f.options.analyze=async value=>{prompt=value;calls++;return '开场正文与用户回应的精简梦境摘要'};clickStoryTool(f,'dream');const form=f.host.querySelector('.if-dream-dialog form');form.elements.online.checked=false;form.elements.offline.checked=true;form.dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();const dream=f.role.ifWorld.dreams[0];assert.equal(dream.injectOnline,false);assert.equal(dream.injectOffline,true);assert.equal(dream.roleId,f.role.experienceCharacterId);assert.equal(dream.sourceBranchId,'b');assert.match(dream.content,/开场正文/);assert.match(dream.content,/用户回应/);assert.equal(calls,1);assert.match(prompt,/最多 800 字/);assert.match(prompt,/用户回应/);assert.equal(dream.summaryVersion,1);assert.equal(f.role.ifWorld.branches[0].messages.length,3);assert.equal(f.host.querySelector('.if-dream-dialog'),null)}finally{f.dom.window.close()}});
