 const f=await messageFixture();try{
  f.role.ifWorld.dreams=[{id:'saved-dream',roleId:'r',content:'已有梦境',injectOnline:true,injectOffline:false}];let prompt,calls=0;f.options.analyze=async value=>{prompt=value;calls++;return '仅属于 IF 的封存摘要'};
  clickStoryTool(f,'seal');await flush();assert.match(prompt,/不注入线上或线下聊天/);const archive=f.role.ifWorld.archives[0];assert.equal(archive.content,'仅属于 IF 的封存摘要');assert.equal(archive.messages.length,3);assert.equal(f.role.ifWorld.dreams.length,1);
  await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');assert.ok(f.host.querySelector('.if-sealed-viewer'));assert.equal(f.host.querySelector('.if-compose'),null);assert.match(f.host.querySelector('.if-sealed-transcript').textContent,/开场正文.*用户回应.*后续正文/s);assert.equal(calls,1);
  f.host.querySelector('[data-sealed-close]').click();f.host.querySelector('[data-if-node]').click();assert.ok(f.host.querySelector('.if-opening-card>.if-sealed-stamp'));f.host.querySelector('[data-if-delete-opening]').click();await flush();assert.equal(f.role.ifWorld.branches.length,0);assert.equal(f.role.ifWorld.archives[0].id,archive.id);
  f.host.querySelector('[data-if-archive-view]').click();assert.match(f.host.querySelector('.if-sealed-transcript').textContent,/后续正文/);assert.equal(f.host.querySelector('.if-compose'),null);
 }finally{f.dom.window.close()}
