test('IF delete removes only its branch, retains dreams, and returns to index',{skip:!JSDOM},async()=>{const f=await messageFixture();try{f.role.ifWorld.dreams=[{id:'saved-dream',roleId:'r',content:'保留梦境'}];f.role.ifWorld.branches.push({...JSON.parse(JSON.stringify(f.role.ifWorld.branches[0])),id:'keep'});f.role.ifWorld.lastBranchId='b';const source=JSON.stringify(f.role.lifeTimeline);clickStoryTool(f,'delete');await flush();assert.deepEqual(Array.from(f.role.ifWorld.branches,b=>b.id),['keep']);assert.equal(f.role.ifWorld.dreams[0].content,'保留梦境');assert.equal(f.role.ifWorld.lastBranchId,undefined);assert.equal(JSON.stringify(f.role.lifeTimeline),source);assert.ok(f.host.querySelector('.if-index'))}finally{f.dom.window.close()}});
test('IF sealing that finishes after a role switch saves to its original role only',{skip:!JSDOM},async()=>{const f=await messageFixture();try{let finish;f.options.analyze=()=>new Promise(resolve=>finish=resolve);clickStoryTool(f,'seal');const other={experienceCharacterId:'other',name:'乙',lifeTimeline:{entries:[]}};f.options.state.characters.push(other);f.options.state.char=1;f.w.IrisIfWorld.mount(f.options,f.host);finish('原角色封存');await flush();assert.equal(f.role.ifWorld.archives[0].content,'原角色封存');assert.equal(other.ifWorld,undefined);assert.ok(!f.host.textContent.includes('原角色封存'))}finally{f.dom.window.close()}});

test('entering an existing IF opening shows the latest content while redraws preserve a reader away from the bottom',{skip:!JSDOM},async()=>{const f=fixture();try{Object.defineProperty(f.w.HTMLElement.prototype,'scrollHeight',{configurable:true,get(){return this.classList.contains('if-story-body')?1200:0}});Object.defineProperty(f.w.HTMLElement.prototype,'clientHeight',{configurable:true,get(){return 300}});f.role.ifWorld.branches[0].messages=[{mine:false,text:'开场'},{mine:true,text:'后续'},{mine:false,text:'更后面的正文'}];f.host.scrollTop=240;f.host.closest('.experiences-page').scrollTop=180;await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');assert.equal(f.host.scrollTop,0);assert.equal(f.host.closest('.experiences-page').scrollTop,0);assert.equal(f.host.querySelector('.if-story-body').scrollTop,1200);f.host.querySelector('.if-story-body').scrollTop=100;contextIfMessage(f,0);assert.equal(f.host.querySelector('.if-story-body').scrollTop,100);f.w.IrisIfWorld.back();f.host.querySelector('[data-if-node]').click();f.host.querySelector('[data-if-open]').click();assert.equal(f.host.querySelector('.if-story-body').scrollTop,1200)}finally{f.dom.window.close()}});
test('legacy IF original-world snapshots are refreshed once for scoped worldbooks without changing story history',{skip:!JSDOM},async()=>{const f=fixture();try{f.options.ifScopedGlobalWorldbooks=true;f.role.ifWorld.branches[0].originalWorld='旧快照里的全局私密设定';f.role.ifWorld.branches[0].messages=[{mine:false,text:'原有剧情'},{mine:true,text:'继续眼前的事'}];f.options.analyze=async prompt=>{assert.ok(!prompt.includes('旧快照里的全局私密设定'));assert.ok(prompt.includes('原世界的城镇与学校设定'));return'新的剧情'};await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');f.host.querySelector('[data-if-reply]').click();await flush();assert.equal(f.role.ifWorld.branches[0].worldbookScopeVersion,1);assert.equal(f.role.ifWorld.branches[0].messages[0].text,'原有剧情')}finally{f.dom.window.close()}});

const adaptedIdentity=()=>({summary:'少年药铺学徒',occupation:'跟随药师学习辨认药草',socialPosition:'凡俗小镇的普通学徒',background:'保留既有家庭关系，以师授学习对应原有求学',resources:'靠学徒生活供给与基础辨药技能，不拥有成年后的资产',relationships:'沿用已经确认的重要人物关系',eventAdaptation:'入学对应进入药铺学习，不改变该节点的成长意义',coreTraits:'克制认真，保留原有表达方式与价值观'});
test('identity adaptation and opening use one request, persist only in the branch and continue from the same identity',{skip:!JSDOM},async()=>{const f=fixture();try{f.options.ifIdentityAdaptation=true;f.role.details='成年后经营现代公司，性格克制认真。';f.role.ifWorld.branches[0].settings.worldId='xianxia';const original=JSON.stringify({name:f.role.name,details:f.role.details,timeline:f.role.lifeTimeline});let calls=0;f.options.analyze=async(prompt,owner,request)=>{calls++;if(calls===1){assert.equal(request.jsonMode,true);assert.match(prompt,/同一次响应/);assert.match(prompt,/成年后经营现代公司/);assert.match(prompt,/不可倒灌/);return{identity:adaptedIdentity(),story:'药铺窗下，甲正辨认新送来的药草。'}}assert.equal(request.jsonMode,false);assert.match(prompt,/本分支已适配身份/);assert.match(prompt,/少年药铺学徒/);assert.ok(!prompt.includes('本次合并生成：世界身份适配与剧情'));return'甲将药草分开放好。'};f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(calls,1);const branch=f.role.ifWorld.branches[0];assert.equal(branch.worldIdentity.worldId,'xianxia');assert.equal(branch.worldIdentity.adaptedAge,12);assert.equal(branch.worldIdentity.summary,'少年药铺学徒');assert.equal(branch.messages[0].text,'药铺窗下，甲正辨认新送来的药草。');assert.ok(!f.host.querySelector('.if-history').textContent.includes('"identity"'));assert.equal(JSON.stringify({name:f.role.name,details:f.role.details,timeline:f.role.lifeTimeline}),original);f.host.querySelector('.if-compose textarea').value='我走近药铺';f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();f.host.querySelector('[data-if-reply]').click();await flush();assert.equal(calls,2);assert.equal(branch.worldIdentity.summary,'少年药铺学徒');assert.equal(f.role.ifWorld.branches[0].messages.length,3);const snapshot=JSON.parse(JSON.stringify(f.options.state));f.options.state.characters=snapshot.characters;f.w.eval(fs.readFileSync(require.resolve('../scripts/if-world.js'),'utf8'));f.w.IrisIfWorld.mount(f.options,f.host);await f.w.IrisIfWorld.openFromNode(f.options,f.host,'n');assert.equal(f.options.state.characters[0].ifWorld.branches[0].worldIdentity.summary,'少年药铺学徒');assert.equal(calls,2)}finally{f.dom.window.close()}});
test('malformed adaptation or failed persistence cannot save half an identity or an opening',{skip:!JSDOM},async()=>{for(const failingSave of [false,true]){const f=fixture();try{f.options.ifIdentityAdaptation=true;f.role.ifWorld.branches[0].settings.worldId='ancient';f.options.analyze=async()=>failingSave?{identity:adaptedIdentity(),story:'开场正文'}:{identity:{summary:'不完整身份'},story:'不能单独保存的正文'};if(failingSave)f.options.persist=async()=>{throw Error('disk full')};f.host.querySelector('.if-compose textarea').value='我的介入';f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(f.role.ifWorld.branches[0].worldIdentity,undefined);assert.equal(f.role.ifWorld.branches[0].messages.length,0);assert.equal(f.host.querySelector('.message-input').value,'我的介入');assert.match(f.host.querySelector('.if-feedback').textContent,failingSave?/disk full/:/返回不完整/)}finally{f.dom.window.close()}}});
test('changing the world during identity generation rejects the stale result without switching it back',{skip:!JSDOM},async()=>{const f=fixture();try{f.options.ifIdentityAdaptation=true;f.role.ifWorld.branches[0].settings.worldId='ancient';let resolve;f.options.analyze=()=>new Promise(done=>resolve=done);f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));f.role.ifWorld.branches[0].settings={worldId:'apocalypse'};resolve({identity:adaptedIdentity(),story:'迟到的古代开场'});await flush();assert.equal(f.role.ifWorld.branches[0].settings.worldId,'apocalypse');assert.equal(f.role.ifWorld.branches[0].worldIdentity,undefined);assert.equal(f.role.ifWorld.branches[0].messages.length,0)}finally{f.dom.window.close()}});
test('original world keeps a plain story response and does not request a new identity',{skip:!JSDOM},async()=>{const f=fixture();try{f.options.ifIdentityAdaptation=true;let calls=0;f.options.analyze=async(prompt,owner,request)=>{calls++;assert.equal(request.jsonMode,false);assert.ok(!prompt.includes('本次合并生成：世界身份适配与剧情'));return'原世界的故事'};f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(calls,1);assert.equal(f.role.ifWorld.branches[0].worldIdentity,undefined);assert.equal(f.role.ifWorld.branches[0].messages[0].text,'原世界的故事')}finally{f.dom.window.close()}});

test('changing between built-in or custom worlds resets only the world preview scroll position',{skip:!JSDOM},()=>{const f=fixture();try{f.host.querySelector('[data-if-view="settings"]').click();f.host.querySelector('[data-if-setting-tab="world"]').click();const select=f.host.querySelector('[name=worldId]'),preview=f.host.querySelector('[data-if-world-preview]');for(const [world,title] of [['chinese-folklore','人间与异类'],['ghost-city','亡者的城市'],['gothic','地域与时代'],['original','原世界的城镇与学校设定']]){preview.scrollTop=180;preview.scrollLeft=20;f.host.scrollTop=80;select.value=world;select.dispatchEvent(new f.w.Event('change'));assert.equal(preview.scrollTop,0);assert.equal(preview.scrollLeft,0);assert.match(preview.textContent,new RegExp(title));assert.equal(f.host.scrollTop,80)}assert.equal(f.calls(),0)}finally{f.dom.window.close()}});

test('submitted intervention is absent from the entered composer and a new pending draft survives opening completion',{skip:!JSDOM},async()=>{const f=fixture();try{let resolve;f.options.analyze=()=>new Promise(done=>resolve=done);f.host.querySelector('.if-compose textarea').value='原本填写的介入节点';f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));assert.equal(f.host.querySelector('.message-input').value,'');const field=f.host.querySelector('.message-input');field.value='接下来想说的话';field.dispatchEvent(new f.w.Event('input'));resolve('开场剧情');await flush();assert.equal(f.host.querySelector('.message-input').value,'接下来想说的话');assert.equal(f.role.ifWorld.branches[0].intervention,'原本填写的介入节点');assert.equal(f.role.ifWorld.branches[0].messages[0].text,'原本填写的介入节点')}finally{f.dom.window.close()}});
test('IF takeover and paragraph requirements are explicit and take priority over generic world restrictions',{skip:!JSDOM},async()=>{for(const agency of ['takeover','no-takeover']){const f=fixture();try{Object.assign(f.role.ifWorld.branches[0].settings,{worldId:'galgame',userAgency:agency,paragraphCountMin:4,paragraphCountMax:6,wordCount:500,paragraphRequirement:'short'});let prompt;f.options.analyze=async value=>{prompt=value;return'角色的回应。'};f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.match(prompt,/500字，4至6个自然段/);assert.match(prompt,/段落组织为短段落/);assert.match(prompt,/不手打空格凑缩进/);assert.match(prompt,/清除八股模板/);assert.match(prompt,agency==='takeover'?/抢话已启用：本轮故事必须自然写到用户/:/不抢话已启用：不补写用户/);assert.ok(prompt.lastIndexOf('本轮输出要求')>prompt.indexOf('Galgame'))}finally{f.dom.window.close()}}});

test('partial legacy settings use default takeover and paragraph range while explicit changes take effect on the next request',{skip:!JSDOM},async()=>{const f=fixture();try{assert.equal(f.host.querySelector('[name=userAgency]').value,'takeover');assert.equal(f.host.querySelector('[name=paragraphCountMin]').value,'10');assert.equal(f.host.querySelector('[name=paragraphCountMax]').value,'15');let prompts=[];f.options.analyze=async prompt=>{prompts.push(prompt);return'新的正文。'};f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.match(prompts[0],/抢话已启用/);assert.match(prompts[0],/10至15个自然段/);assert.match(prompts[0],/长段、短段、长段、短段交替组织/);Object.assign(f.role.ifWorld.branches[0].settings,{userAgency:'no-takeover',paragraphCountMin:2,paragraphCountMax:4,paragraphRequirement:'long'});f.host.querySelector('[data-if-reply]').click();await flush();assert.match(prompts[1],/不抢话已启用/);assert.match(prompts[1],/2至4个自然段/);assert.match(prompts[1],/段落组织为长段落/);assert.ok(!prompts[1].includes('长段、短段、长段、短段交替组织'))}finally{f.dom.window.close()}});

test('interacting with the floating assistant keeps IF function and message menus available for explanation',{skip:!JSDOM},async()=>{const f=await messageFixture();try{const assistant=f.w.document.createElement('div');assistant.className='iris-guide-widget';assistant.innerHTML='<button type="button">查看功能</button>';f.w.document.body.append(assistant);f.host.querySelector('[data-if-tools-toggle]').click();assert.equal(f.host.querySelector('.if-story-tools-menu').hidden,false);assistant.querySelector('button').click();assert.equal(f.host.querySelector('.if-story-tools-menu').hidden,false);contextIfMessage(f,0);const actions=f.host.querySelector('.if-message-actions');assistant.querySelector('button').click();assert.equal(actions.isConnected,true);assert.equal(f.host.querySelector('.if-message-actions'),actions)}finally{f.dom.window.close()}});

test('IF defaults to strangers, leaves the final response open and cleans AI dashes while preserving user input',{skip:!JSDOM},async()=>{const f=fixture();try{let prompt,calls=0;f.options.analyze=async value=>{prompt=value;calls++;return'甲翻到18—20岁的那页——纸角微卷。\n\n甲递出笔——“可以写下名字吗？”'};f.host.querySelector('.if-compose textarea').value='我在门外——等候';f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();assert.equal(calls,1);assert.match(prompt,/每条 IF 分支默认角色与用户互不认识/);assert.match(prompt,/已建立的关系不因下一轮回复而重置/);assert.match(prompt,/使用本次用户资料提供的真实姓名/);assert.match(prompt,/无论抢话还是不抢话，最后一段/);assert.match(prompt,/不在末段替用户接完这次回应/);const messages=f.role.ifWorld.branches[0].messages;assert.equal(messages[0].text,'我在门外——等候');assert.ok(!/[–—―⸺⸻]/.test(messages[1].text));assert.match(messages[1].text,/18至20岁/);assert.match(messages[1].text,/甲递出笔，“可以写下名字吗？”/);assert.match(f.host.querySelector('.if-message.is-user').textContent,/我在门外——等候/)}finally{f.dom.window.close()}});

test('IF reroll hides the old reply while spinning and atomically replaces it with a new perspective-aware reply',{skip:!JSDOM},async()=>{
 const f=fixture();try{
  f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();
  const branch=f.role.ifWorld.branches[0],old=branch.messages.at(-1).text;branch.settings.userPerspective='first';
  let resolve,prompt;f.options.analyze=p=>{prompt=p;return new Promise(r=>resolve=r)};
  f.host.querySelector('[data-if-reply]').click();
  assert.equal(f.host.querySelector('[data-if-reply]').getAttribute('aria-busy'),'true');
  assert.ok(!f.host.querySelector('.if-history').textContent.includes(old));
  assert.match(prompt,/用户叙述严格使用第一人称“我”/);assert.match(prompt,/上一版回复已作废/);
  resolve('我接过书，他让开了门口。');await flush();
  assert.equal(f.role.ifWorld.branches[0].messages.length,1);
  assert.equal(f.role.ifWorld.branches[0].messages[0].text,'我接过书，他让开了门口。');
  assert.equal(f.host.querySelector('[data-if-reply]').getAttribute('aria-busy'),'false');
  f.host.querySelector('[data-if-reply]').click();resolve('我接过书，他让开了门口。');await flush();
  assert.equal(f.role.ifWorld.branches[0].messages.length,1);assert.match(f.host.textContent,/模型返回了相同的正文/);
  assert.ok(f.host.querySelector('.if-history').textContent.includes('我接过书'));
 }finally{f.dom.window.close()}
});

test('custom IF entry stays first, creates an isolated age-bound scenario, and uses the existing settings and generator',{skip:!JSDOM},async()=>{
 const f=fixture();try{
  f.w.IrisIfWorld.back();const timeline=JSON.stringify(f.role.lifeTimeline);
  assert.ok(f.host.querySelector('.if-node-list').firstElementChild.hasAttribute('data-if-custom'));
  assert.ok(f.host.querySelector('[data-if-custom]>.if-timeline-bow'));
  f.host.querySelector('[data-if-custom]').click();const form=f.host.querySelector('.if-custom-dialog form');
  form.elements.title.value='雨夜的书店';form.elements.age.value='20';form.elements.age.dispatchEvent(new f.w.Event('input'));form.elements.details.value='二十岁时在书店初次相遇，窗外下雨。';
  form.dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();
  const branch=f.role.ifWorld.branches.find(b=>b.sourceKind==='custom');assert.ok(branch);assert.equal(branch.nodeSnapshot.startAge,20);assert.equal(branch.intervention,'二十岁时在书店初次相遇，窗外下雨。');assert.equal(branch.growthBinding.stageId,'s');assert.equal(JSON.stringify(f.role.lifeTimeline),timeline);
  assert.ok(f.host.querySelector('[data-if-settings]'));assert.equal(f.host.querySelector('.if-compose textarea').value,'');
  f.options.ifBranchGrowthBinding=(owner,item)=>item.growthBinding;
  let prompt;f.options.analyze=async p=>{prompt=p;return '雨滴打在门前，甲合上了书。'};
  f.host.querySelector('.if-compose').dispatchEvent(new f.w.Event('submit',{cancelable:true}));await flush();
  assert.match(prompt,/用户自定义情境建立/);assert.match(prompt,/二十岁时在书店初次相遇/);
  assert.equal(f.role.ifWorld.branches.find(b=>b.id===branch.id).messages.length,1);
  f.w.IrisIfWorld.back();assert.equal(f.host.querySelector('.if-node-list').children[1].dataset.ifCustomBranch,branch.id);
  f.host.querySelector('[data-if-custom-branch]').click();assert.ok(f.host.querySelector('.if-story-page'));
 }finally{f.dom.window.close()}
});

test('played timeline cards sort by last play rather than timeline age and unplayed cards stay below them',{skip:!JSDOM},async()=>{
 const f=fixture();try{
  f.role.lifeTimeline.entries.push({id:'newer',title:'毕业',startAge:22},{id:'unplayed',title:'童年',startAge:5});
  f.role.ifWorld.branches[0].messages=[{mine:false,text:'入学开场'}];f.role.ifWorld.branches[0].lastPlayedAt=100;
  f.role.ifWorld.branches.push({...JSON.parse(JSON.stringify(f.role.ifWorld.branches[0])),id:'b2',sourceNodeId:'newer',nodeSnapshot:{id:'newer',title:'毕业',startAge:22},lastPlayedAt:200});
  f.w.IrisIfWorld.back();assert.deepEqual(Array.from(f.host.querySelectorAll('[data-if-node]'),b=>b.dataset.ifNode),['newer','n','unplayed']);
  f.host.querySelector('[data-if-node="n"]').click();f.host.querySelector('[data-if-open]').click();await flush();f.w.IrisIfWorld.back();
  assert.equal(f.host.querySelector('.if-node-list').firstElementChild.hasAttribute('data-if-custom'),true);
  assert.equal(f.host.querySelectorAll('[data-if-node]')[0].dataset.ifNode,'n');
 }finally{f.dom.window.close()}
});

